                "interval": 3
              },
              "type": "ApiConnection",
              "inputs": {
                "host": {
                  "connection": {
                    "name": "@parameters('$connections')['servicebus']['connectionId']"
                  }
                },
                "method": "get",
                "path": "/@{encodeURIComponent(encodeURIComponent('test'))}/messages/head/peek",
                "queries": {
                  "queueType": "Main",
                  "sessionId": "Next Available"
                }
              }
            }
          },
          "actions": {
            "Close_a_session_in_the_queue": {
              "runAfter": {
                "Until": [
                  "Succeeded"
                ]
              },
              "type": "ApiConnection",
              "inputs": {
                "host": {
                  "connection": {
                    "name": "@parameters('$connections')['servicebus']['connectionId']"
                  }
                },
                "method": "delete",
                "path": "/@{encodeURIComponent(encodeURIComponent('test'))}/sessions/@{encodeURIComponent(triggerBody()?['SessionId'])}/close"
              }
            },
            "Complete_initial_message_in_queue": {
              "runAfter": {
                "Send_initial_message_to_topic": [
                  "Succeeded"
                ]
              },
              "type": "ApiConnection",
              "inputs": {
                "host": {
                  "connection": {
                    "name": "@parameters('$connections')['servicebus']['connectionId']"
                  }
                },
                "method": "delete",
                "path": "/@{encodeURIComponent(encodeURIComponent('test'))}/messages/complete",
